export function ClarificationReview(){return <section className="panel ops-panel"><h2>Workflow decisions to confirm</h2><p>These are unresolved business rules, distinct from errors and overdue work.</p>{clarificationItems.map(item=><Clarification key={item[0]} id={item[0]}/>)}</section>;}
