 if(c.type==='report-draft'&&c.kind==='final')return 'Final laboratory report draft saved. Next: submit it for approval.';
 if(c.type==='report-action'&&c.kind==='final'){if(c.action==='submit')return `Final laboratory report submitted. Next: ${name(holder(actor,'finalApproval'))} approves and signs it.`;if(c.action==='approve')return `Final laboratory report approved and signed by ${name(actor.id)}. The job is complete.`;if(c.action==='return')return `Final laboratory report returned to ${name(holder(actor,'reporting'))} for correction.`;}
 if(c.type==='handover-receive')return 'Samples/containers receipt recorded with your name and time.';
 if(c.type==='add-validation'&&!c.steps.length){const lead=holder(actor,'pvtTeamLead');return `Validation requested for ${job.jobNumber} (Sample ${c.sampleIds.join(', ')}). Earlier work and reports are unchanged. Next: ${lead?name(lead)+' (PVT Team Lead) chooses the steps and engineers':'the PVT Team Lead is not configured; the request waits until an administrator assigns that duty'}.`;}
 if(c.type==='add-validation'){const lead=holder(actor,'pvtTeamLead');return `Validation added to ${job.jobNumber} (Sample ${c.sampleIds.join(', ')}: ${c.steps.length} activit${c.steps.length===1?'y':'ies'}). Earlier work and reports are unchanged. Next: ${lead?name(lead)+' (PVT Team Lead) assigns the activities':'the PVT Team Lead is not configured, so the work waits as Unassigned until an administrator assigns that duty'}.`;}
