const human=(key:string)=>key.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,c=>c.toUpperCase());
/** Field values with their unit fields merged ("BHP 3150 psi"); empty values are listed as missing. */
function fieldRows(data:Record<string,unknown>){return Object.entries(data).filter(([k])=>!k.endsWith('Unit')).map(([k,v])=>[human(k),String(v??'').trim()?String(v)+(data[k+'Unit']&&/\d/.test(String(v))?' '+data[k+'Unit']:''):'—'] as const);}
/**
 * Everything the sampling approver needs in one place, from the submitted snapshot: job, instructions, assignments,
 * preparation, samples and containers, sampling data, events, attachments, handover and missing information.
 */
function SamplingReview({job,actor,run,onSampling}:{job:JobRecord;actor:Actor;run:(c:Command)=>boolean;onSampling:(stage?:string,sample?:string)=>void}){
 const o=operationsFor(job);const reviews=o.samplingData||[];const d=reviews.at(-1);const roles=actorRoles(actor);const st=samplingStatus(job,roles);
 const name=(id?:string)=>actor.employees.find(e=>e.id===id)?.name||'Not recorded';const when=(v?:string)=>v?new Date(v).toLocaleString():'—';
 const approver=holder(actor,'samplingApproval');const isApprover=!!approver&&actor.id===approver&&hasAccess(actor,'sampling');const isLead=actor.id===job.assignedEngineerId&&hasAccess(actor,'sampling');
 const [comments,setComments]=useState<ReviewComment[]>([{target:'',label:'',text:''}]),[general,setGeneral]=useState(''),[reason,setReason]=useState('');
 useUnsaved(!!general||comments.some(c=>c.text)||!!reason);
 if(!dataReviewRequired(job))return <section className="panel ops-panel"><h2>Sampling data review</h2><p>This job’s sampling report started before separate data review. It continues with its recorded report path below.</p></section>;
 type Snap={samples:JobRecord['samples'];events:JobRecord['events'];coordinationTasks:JobRecord['coordinationTasks'];coordinationDetails:Record<string,unknown>;preparation:string};
 const snap:Snap=d&&d.status!=='Reopened'?JSON.parse(d.snapshot):{samples:job.samples,events:job.events,coordinationTasks:job.coordinationTasks,coordinationDetails:job.coordinationDetails||{},preparation:job.stages?.find(x=>x.name==='Sampling Preparation')?.status||''};
 const issues=samplingIssues({samplingSource:job.samplingSource,samples:snap.samples,stages:snap.preparation?[{name:'Sampling Preparation',status:snap.preparation}]:[]});
 const targets=reviewTargets({samples:snap.samples});const team=samplingTeam(job);const h=o.handover;
 const steps:[string,boolean,string][]=[['Data submitted',!!d&&d.status!=='Reopened',d&&d.status!=='Reopened'?name(d.submittedBy)+' · '+when(d.submittedAt):'Not yet'],['Data approved',d?.status==='Approved',d?.status==='Approved'?name(d.reviewedBy)+' · '+when(d.reviewedAt):d?.status==='Returned'?'Returned '+when(d.reviewedAt):'Pending'],['Report generated',!!latest(o.samplingReports)&&d?.status==='Approved',latest(o.samplingReports)?'Version '+latest(o.samplingReports)!.version+' · '+latest(o.samplingReports)!.status:'Pending'],['Report approved',latest(o.samplingReports)?.status==='Approved','Pending' ]];
 if(latest(o.samplingReports)?.status==='Approved')steps[3][2]=name(latest(o.samplingReports)!.approvedBy)+' · '+when(latest(o.samplingReports)!.approvedAt);
 const goTo=(target:string)=>{const sample=target.startsWith('sample:')?target.split(':')[1]:undefined;onSampling(target==='preparation'?'type':target==='job'?'type':'bottomhole',sample);};
 return <section className="panel ops-panel sampling-review" id="sampling-review">
  <div className="panel-heading"><div><span className="eyebrow">SAMPLING DATA REVIEW</span><h2>{st.label}</h2><p>Next: {st.next}{st.owner?' · '+name(st.owner):''}. Data approval and sampling-report approval are separate steps by {approver?name(approver):'the sampling approver (not configured)'}.</p></div></div>
  <ol className="review-timeline">{steps.map(([label,done,detail])=><li key={label} className={done?'is-complete':''}>{done?<CheckCircle2 size={16}/>:<Circle size={16}/>}<span><strong>{label}</strong><small>{detail}</small></span></li>)}</ol>
  {d?.status==='Returned'&&<div className="returned-box" role="status"><h3>Returned for correction · {name(d.reviewedBy)} · {when(d.reviewedAt)}</h3><p className="instructions-text">{d.general}</p><ul>{d.comments.map((c,i)=><li key={i}><strong>{c.label}</strong>: {c.text} {(isLead||team.includes(actor.id))&&<button type="button" className="text-button" onClick={()=>goTo(c.target)}>Open section →</button>}</li>)}</ul>{isLead?<button className="primary-button" onClick={()=>onSampling('report')}>Correct and resubmit</button>:team.includes(actor.id)?<p>You can help correct the data. {name(job.assignedEngineerId)} resubmits it.</p>:null}</div>}
  {d?.status==='Reopened'&&<p className="revision-banner">Approved data reopened by {name(d.reopenedBy)} on {when(d.reopenedAt)}: {d.reason}. The earlier approval and report versions are kept in the history.</p>}
  {!d&&<p className="locked-note"><AlertCircle size={16}/> No sampling data has been submitted yet. {name(job.assignedEngineerId)} submits it from the sampling workspace.</p>}
  <h3>Missing information and validation</h3>{issues.length?<ul className="issue-list">{issues.map((x,i)=><li key={i}><strong>{x.label}</strong>: {x.text}</li>)}</ul>:<p className="ops-success">No missing required information detected.</p>}
  <div className="ops-two-columns review-columns">
   <section><h3>Job details</h3><dl className="ops-facts">{([['Job',job.jobNumber],['Client',job.clientName],['Field',job.fieldArea],['Well',job.wellMode==='multiple'?(job.wells||[]).filter(Boolean).join(', '):job.well],['Sampling type',job.samplingSource],['Due date',job.dueDate],['Client focal point',[job.clientFocalPoint,job.clientFocalPointContact].filter(Boolean).join(' · ')]] as [string,string|undefined][]).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v||'Not recorded'}</dd></div>)}</dl></section>
   <section><h3>Assignments</h3><dl className="ops-facts"><div><dt>Accountable</dt><dd>{name(job.assignedEngineerId)}</dd></div><div><dt>Supporting</dt><dd>{team.slice(1).map(name).join(', ')||'None'}</dd></div><div><dt>Driver</dt><dd>{name(job.assignedDriverId)}</dd></div><div><dt>Submitted</dt><dd>{d&&d.status!=='Reopened'?name(d.submittedBy)+' · '+when(d.submittedAt)+' · v'+d.version:'Not submitted'}</dd></div></dl>{d?.note&&<p>Submission note: {d.note}</p>}</section>
  </div>
  <section><h3>Sampling instructions</h3><p className="instructions-text">{job.samplingInstructions||'No specific sampling instructions recorded.'}</p></section>
  <section><h3>Preparation</h3><p>Preparation step: <strong>{snap.preparation||'Not recorded'}</strong>{preparationDone({stages:snap.preparation?[{name:'Sampling Preparation',status:snap.preparation}]:[]})?'':' · not complete'}</p>{(snap.coordinationTasks||[]).length>0&&<ul className="check-list">{snap.coordinationTasks!.map(t=><li key={t.id}>{t.completed?'✓':'•'} {t.label}{t.completed?' · '+name(t.completedBy):' · pending'}</li>)}</ul>}<details><summary>Coordination details</summary><dl className="ops-facts">{fieldRows(snap.coordinationDetails||{}).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl></details></section>
  <section><h3>Samples and containers</h3><div className="ops-table-wrap"><table><thead><tr><th>Sample</th><th>Container</th><th>Sampler</th><th>Prepared</th><th>Data sheet</th></tr></thead><tbody>{(snap.samples||[]).map(x=><tr key={x.id}><td>{x.id}</td><td>{containerLabel(x,'Not recorded')}</td><td>{[x.sampler,x.samplerSerial].filter(Boolean).join(' · ')||'—'}</td><td>{x.preparedBy?name(x.preparedBy)+' · '+when(x.preparedAt):'—'}</td><td>{x.dataComplete?'Complete · '+name(x.dataCompletedBy):'Not complete'}</td></tr>)}</tbody></table></div></section>
  <section><h3>Sampling data</h3>{(snap.samples||[]).map(x=><details key={x.id} className="review-sample"><summary>Sample {x.id} · {containerLabel(x,'container not recorded')}</summary><dl className="ops-facts">{fieldRows({depth:x.depth,pressure:x.pressure,temperature:x.temperature,calibrationStatus:x.calibrationStatus,pressureTestStatus:x.pressureTestStatus,equipmentCondition:x.equipmentCondition,...x.fieldData}).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>{x.notes&&<p>Remarks: {x.notes}</p>}{x.preparationRemarks&&<p>Preparation remarks: {x.preparationRemarks}</p>}</details>)}</section>
  <section><h3>Sequence of events</h3>{(snap.events||[]).length?<ul className="check-list">{snap.events!.map((e,i)=><li key={i}>{e.date} {e.time} · {e.description}</li>)}</ul>:<p>No events recorded.</p>}</section>
  <section><h3>Attachments and handover</h3><p>{job.scopeOfWorkAttachment?<a href={job.scopeOfWorkAttachment.dataUrl} download={job.scopeOfWorkAttachment.name}>Client request document: {job.scopeOfWorkAttachment.name}</a>:'No attachments recorded.'}</p><p>Handover: {h?.receivedAt?'Received by '+name(h.receivedBy):h?'Sent by '+name(h.sentBy)+' · '+when(h.sentAt):'Not yet — driver '+name(job.assignedDriverId)+' transports after the sampling report is approved.'}</p></section>
  {d?.status==='Submitted'&&(isApprover?<section className="review-actions"><h3>Your decision</h3><div className="ops-actions"><button className="primary-button" onClick={()=>run({type:'data-approve'})}>Approve sampling data</button></div><details className="return-form"><summary>Return for correction</summary><p>Name each affected section or sample and explain exactly what must change.</p>{comments.map((c,i)=><div key={i} className="return-row"><select aria-label={'Section for comment '+(i+1)} value={c.target} onChange={e=>{const t=targets.find(x=>x.target===e.target.value);setComments(comments.map((x,j)=>j===i?{...x,target:e.target.value,label:t?.label||''}:x));}}><option value="">Select section or sample</option>{targets.map(t=><option key={t.target} value={t.target}>{t.label}</option>)}</select><input aria-label={'Comment '+(i+1)} value={c.text} placeholder="What must be corrected" onChange={e=>setComments(comments.map((x,j)=>j===i?{...x,text:e.target.value}:x))}/>{comments.length>1&&<button type="button" className="text-button" onClick={()=>setComments(comments.filter((_,j)=>j!==i))}>Remove</button>}</div>)}<button type="button" className="text-button" onClick={()=>setComments([...comments,{target:'',label:'',text:''}])}>+ Add another comment</button><label>Correction explanation *<textarea value={general} onChange={e=>setGeneral(e.target.value)}/></label><button className="outline-button" onClick={()=>{if(run({type:'data-return',general,comments:comments.filter(c=>c.target||c.text)})){setComments([{target:'',label:'',text:''}]);setGeneral('');}}}>Return to {name(job.assignedEngineerId)}</button></details></section>:<p>Waiting for {approver?name(approver):'the sampling approver (not configured)'} to review.</p>)}
  {d?.status==='Approved'&&(isLead||isApprover)&&!h&&!o.scopeConfirmedAt&&<details className="return-form"><summary>Correct approved data</summary><p>Reopening keeps the earlier approval and report versions in the history and requires a new data review and a new report approval.</p><label>Reason *<textarea value={reason} onChange={e=>setReason(e.target.value)}/></label><button className="outline-button" onClick={()=>{if(run({type:'data-reopen',reason}))setReason('');}}>Reopen sampling data</button></details>}
  {reviews.length>0&&<details><summary>Submission history ({reviews.length})</summary>{[...reviews].reverse().map((r:DataReview)=><article className="ops-history" key={r.version}><strong>v{r.version} · {r.status}</strong><p>{r.status==='Reopened'?'Reopened by '+name(r.reopenedBy)+' · '+when(r.reopenedAt)+' · '+r.reason:'Submitted by '+name(r.submittedBy)+' · '+when(r.submittedAt)}{r.reviewedBy?' · Reviewed by '+name(r.reviewedBy)+' · '+when(r.reviewedAt):''}</p>{r.general&&<p>{r.general}</p>}{r.comments.map((c,i)=><p key={i}><small>{c.label}: {c.text}</small></p>)}</article>)}</details>}
 </section>;
}

type LabItem={job:JobRecord;a:ActivityRecord};
const queueDefs:[string,string,(a:ActivityRecord)=>boolean][]=[
 ['unassigned','Awaiting assignment',a=>!a.owner&&a.status!=='Completed'],
 ['progress','Assigned / in progress',a=>!!a.owner&&['Unassigned','Scheduled','In Progress'].includes(a.status)],
 ['review','Awaiting workbook review',a=>a.status==='Workbook Submitted'||a.status==='QC Returned'],
 ['returned','Returned for correction',a=>a.status==='Changes Requested'],
 ['qc','Awaiting QC',a=>a.status==='Awaiting QC'],
 ['done','Approved / completed',a=>a.status==='Completed'],
];
/**
 * Laboratory by team: separate PVT and Chemical views. Each person lands on their own team's view (from duties,
 * current assignments, then team membership). Rows and buttons come from the shared work-item model, so counts
 * match My work. Team leads keep a separate queue selection per team.
 */
export function LabWorkspace({jobs,actor,work,isNew,onOpenItem,onOpen}:{jobs:JobRecord[];actor:Actor;work:ReturnType<typeof workItems>;isNew:(i:WorkItem)=>boolean;onOpenItem:(i:WorkItem)=>void;onOpen:(item:LabItem)=>void}){
 const roles=actorRoles(actor);const name=(id?:string)=>actor.employees.find(e=>e.id===id)?.name||'Not assigned';const me=actor.id;
 const items:LabItem[]=jobs.flatMap(job=>operationsFor(job).activities.filter(a=>a.required).map(a=>({job,a})));
 const mineStreams=employeeStreams(actor,jobs);
 const leadOf=(['PVT','Chemical'] as const).filter(stream=>roles[streamLead(stream)]===me&&hasAccess(actor,'analysis'));
 const isQc=!!roles.qcReviewer&&roles.qcReviewer===me&&hasAccess(actor,'analysis');
 const overview=me==='MA001'||roles.pvtSupervisor===me||roles.scopeSelector===me||hasAccess(actor,'companyOverview');
 const [stream,setStreamState]=useState<Stream>(()=>{try{const v=sessionStorage.getItem('vaps-lab-stream:'+me);if(v==='PVT'||v==='Chemical')return v;}catch{/* default */}return mineStreams[0]||'PVT';});
 const setStream=(v:Stream)=>{setStreamState(v);try{sessionStorage.setItem('vaps-lab-stream:'+me,v);}catch{/* not critical */}};
 const urgent=(st:Stream)=>['review','unassigned','returned','qc','progress'].find(id=>items.some(i=>i.a.stream===st&&queueDefs.find(q=>q[0]===id)![2](i.a)))||'unassigned';
 // One queue selection per team, so a person leading both teams keeps each team's view.
 const [queues,setQueues]=useState<Record<Stream,string>>(()=>({PVT:urgent('PVT'),Chemical:urgent('Chemical')}));
 const row=({job,a}:LabItem,showOwner=true)=>{const sample=job.samples?.find(s=>s.id===a.sampleId);const st=labStatus(a);return <tr key={job.id+a.id}><td><button type="button" className="table-job-link" onClick={()=>onOpen({job,a})}>{job.jobNumber}</button><small>{job.clientName}</small></td><td><strong>{a.title}</strong><small>{a.kind==='validation'?'Validation step':a.custom?a.stream+' · other test':a.stream}{a.external?' · '+externalLabel(a):''}</small></td><td><strong>Sample {a.sampleId}</strong><small>{sample?containerLabel(sample):'Container not recorded'}</small></td>{showOwner&&<td><strong>{name(a.owner)}</strong>{teamMismatch(a,actor.teams)&&<small className="flag-note">Not in {a.stream} team</small>}</td>}<td><small>{a.start?`${a.start} → ${a.due}`:'Not scheduled'}</small></td><td><span className={'status-pill lab-'+st.toLowerCase().replace(/[^a-z]+/g,'-')}>{a.external?externalStage(a):st}</span><small>{nextLabAction(a,name,roles)}</small></td><td><button type="button" className="continue-button" onClick={()=>onOpen({job,a})}>Open test <ArrowRight size={13}/></button></td></tr>;};
 const table=(list:LabItem[],empty:string,showOwner=true)=><div className="operations-table-wrap"><table className="operations-table lab-table"><thead><tr><th>Job</th><th>Test</th><th>Sample · container</th>{showOwner&&<th>Assigned</th>}<th>Planned</th><th>Status · next action</th><th aria-label="Action"/></tr></thead><tbody>{list.map(i=>row(i,showOwner))}{!list.length&&<tr className="operations-empty-row"><td colSpan={showOwner?7:6}><strong>{empty}</strong></td></tr>}</tbody></table></div>;
 const inStream=items.filter(i=>i.a.stream===stream);
 // My tasks in this team, using the same rows as My work (Do now first, then Coming up, then Waiting).
 const myNow=work.actions.filter(i=>i.stream===stream&&(i.key.startsWith('test:'))),myReview=work.actions.filter(i=>i.stream===stream&&!i.key.startsWith('test:')&&!i.key.startsWith('assign:'));
 const mySoon=work.upcoming.filter(u=>u.area===stream&&u.key.startsWith('soon-test:'));
 const myWaiting=work.waiting.filter(w=>w.key.startsWith('w-test:')&&inStream.some(i=>w.key==='w-test:'+i.a.id+':'+i.job.id));
 const scopeAlerts=work.alerts.filter(a=>a.kind==='scope'&&a.open.tab.endsWith('stream='+stream));
 const lead=leadOf.includes(stream);const waitingQc=items.filter(({a})=>a.status==='Awaiting QC'&&a.stream===stream);
 const taskRow=(i:WorkItem)=><tr key={i.key}><td><b className="mono">{i.jobNumber}</b><small>{i.client}</small></td><td>{isNew(i)&&<span className="inbox-tag tag-new">New</span>}{i.kind==='returned'&&<span className="inbox-tag tag-returned">Returned</span>}<strong>{i.action}</strong><small>{[i.sample&&'Sample '+i.sample+(i.container?' · '+i.container:''),i.test].filter(Boolean).join(' · ')}</small></td><td><small>{i.dueKind}</small> {i.due||'—'}{i.overdue&&<strong className="ops-overdue">Overdue</strong>}</td><td><button type="button" className="primary-button" onClick={()=>onOpenItem(i)}>{i.button}</button></td></tr>;
 const hasAnything=myNow.length||myReview.length||mySoon.length||myWaiting.length||lead||isQc;
 return <div className="lab-workspace">
  <section className="page-intro operations-page-intro"><div><span className="eyebrow">LABORATORY</span><h1>Laboratory</h1><p>{lead?`You lead the ${stream} team: plan, assign and review here.`:mineStreams.includes(stream)?`Your ${stream} work. The same tasks appear in My work.`:`${stream} work.`}</p></div></section>
  <div className="lab-stream-tabs" role="tablist" aria-label="Laboratory team">{(['PVT','Chemical'] as const).map(st=>{const n=work.actions.filter(i=>i.stream===st||(i.area==='QC'&&i.stream===st)).length;return <button key={st} type="button" role="tab" aria-selected={stream===st} className={stream===st?'active':''} onClick={()=>setStream(st)}>{st}{mineStreams.includes(st)&&<small>{roles[streamLead(st)]===me?'your team (lead)':'your work'}</small>}{n>0&&<b>{n}</b>}</button>;})}</div>
  {lead&&scopeAlerts.length>0&&<p className="scope-note" role="status"><strong>{scopeAlerts.length} new {stream} scope alert{scopeAlerts.length===1?'':'s'}</strong> · {scopeAlerts.map(a=>a.jobNumber+' ('+a.scope+')').join('; ')}. Assign below or from My work.</p>}
  {(myNow.length>0||myReview.length>0)&&<section className="panel operations-register"><div className="panel-heading premium-heading"><div><span className="eyebrow">DO NOW · {stream}</span><h2>Your {stream} tasks</h2></div><span className="event-count">{myNow.length+myReview.length}</span></div><div className="operations-table-wrap"><table className="operations-table lab-table"><thead><tr><th>Job</th><th>Task</th><th>Deadline</th><th aria-label="Action"/></tr></thead><tbody>{[...myReview,...myNow].map(taskRow)}</tbody></table></div></section>}
  {(mySoon.length>0||myWaiting.length>0)&&<details className="panel operations-register"><summary><strong>Coming up and waiting ({mySoon.length+myWaiting.length})</strong></summary><ul className="compact-list">{mySoon.map(u=><li key={u.key}><b className="mono">{u.jobNumber}</b> · {u.what} · {u.after}{u.due?` · Test due ${u.due}`:''}</li>)}{myWaiting.map(w=><li key={w.key}><b className="mono">{w.jobNumber}</b> · {w.what} · waiting on {w.waitingOn}</li>)}</ul></details>}
  {lead&&(()=>{const selected=queueDefs.find(q=>q[0]===queues[stream])||queueDefs[0];return <section className="panel operations-register lead-queues"><div className="panel-heading premium-heading"><div><span className="eyebrow">{stream.toUpperCase()} TEAM LEAD</span><h2>{stream} work queues</h2><p>Team: {(actor.teams?.[stream]||[]).map(name).join(', ')||'no members configured'}.</p></div></div>
   <div className="cockpit-filters queue-tabs" role="group" aria-label={stream+' queues'}>{queueDefs.map(([id,label,test])=><button key={id} type="button" className={queues[stream]===id?'active':''} aria-pressed={queues[stream]===id} onClick={()=>setQueues({...queues,[stream]:id})}>{label} <span className="filter-count">{inStream.filter(i=>test(i.a)).length}</span></button>)}</div>
   {table(inStream.filter(i=>selected[2](i.a)),'Nothing in “'+selected[1]+'”.')}</section>;})()}
  {isQc&&<section className="panel operations-register"><div className="panel-heading premium-heading"><div><span className="eyebrow">QC REVIEW · {stream}</span><h2>QC queue</h2><p>Team-lead-approved workbook versions. Returns go back to the {stream} team lead.</p></div><span className="event-count">{waitingQc.length} WAITING</span></div>{table(waitingQc,'No '+stream+' workbooks waiting for QC.')}</section>}
  {!roles.qcReviewer&&waitingQc.length>0&&(lead||overview)&&<p className="qc-gate" role="status"><strong>QC reviewer not configured.</strong> {waitingQc.length} team-lead-approved {stream} workbook(s) are waiting. An administrator assigns QC review in Settings → Authorization.</p>}
  {overview&&<details className="panel operations-register" open={!hasAnything}><summary><span className="eyebrow">OVERVIEW · {stream}</span> <strong>All {stream} tests ({inStream.length})</strong> <small>Read-only. Actions stay with their configured holders.</small></summary><div className="lab-overview-counts"><div>{labStatuses.map(st=><span key={st}>{st}: {inStream.filter(i=>labStatus(i.a)===st).length}</span>)}</div></div>{table(inStream.filter(i=>i.a.status!=='Completed'),'No open '+stream+' tests.')}</details>}
  {!hasAnything&&!overview&&<p className="lab-empty-note">No {stream} work for you right now. Your tasks always appear in My work.</p>}
 </div>;
}
/** Required tests for final reporting, grouped into the six laboratory states, with each QC-approved version. */
function RequiredTests({job,actor}:{job:JobRecord;actor:Actor}){
 const name=(id?:string)=>actor.employees.find(e=>e.id===id)?.name||'—';const list=operationsFor(job).activities.filter(a=>a.required);
 if(!list.length)return <p>No required laboratory tests yet.</p>;
 return <><div className="lab-status-summary">{labStatuses.map((st:LabStatus)=><span key={st} className={'status-pill lab-'+st.toLowerCase().replace(/[^a-z]+/g,'-')}>{st}: {list.filter(a=>labStatus(a)===st).length}</span>)}</div>
  <div className="ops-table-wrap"><table><thead><tr><th>Test</th><th>Sample</th><th>Status</th><th>QC-approved result</th></tr></thead><tbody>{list.map(a=>{const ok=[...a.files].reverse().find(f=>f.qcApprovedAt);return <tr key={a.id}><td>{a.title} <small>({a.stream}{a.external?' · '+externalLabel(a):''})</small></td><td>{a.sampleId}</td><td>{labStatus(a)}{a.external?<small> · {externalStage(a)}</small>:null}</td><td>{ok?<><FileLink file={ok}/><small>QC: {name(ok.qcApprovedBy)} · {new Date(ok.qcApprovedAt!).toLocaleString()}</small></>:a.status==='Completed'?<small>Completed before QC existed (historical)</small>:'—'}</td></tr>;})}</tbody></table></div></>;
}
